fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Assuming both vectors have equal length, we iterate over the indices
    // and compare element-wise using standard integer ordering.
    let len = a.len();
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        result.push(a[i] <= b[i]);
    }

    result
}